import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.*;

public class ReportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String reportType = req.getParameter("type");
        String startDate = req.getParameter("start");
        String endDate = req.getParameter("end");
        String sortCol = req.getParameter("sort");
        String tenantId = (String) req.getAttribute("X-Tenant-Id");

        if (reportType == null || startDate == null || endDate == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate date format loosely
        if (!startDate.matches("\\d{4}-\\d{2}-\\d{2}") || !endDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date format");
            return;
        }

        // Whitelist report types
        Set<String> validTypes = Set.of("sales", "inventory", "returns", "audit");
        if (!validTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Sort column - allow flexible sorting by user-specified column
        if (sortCol == null || sortCol.isEmpty()) {
            sortCol = "created_at";
        }
        // Basic alphanumeric check - allows underscores for column names
        if (!sortCol.matches("[a-zA-Z_]+")) {
            resp.sendError(400, "Invalid sort column");
            return;
        }

        String query = buildQuery(reportType, startDate, endDate, sortCol, tenantId);
        log.info("Executing report query for tenant=" + tenantId + " type=" + reportType);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            var writer = resp.getWriter();
            writer.write("{\"results\":[");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int colCount = meta.getColumnCount();
            while (rs.next()) {
                if (!first) writer.write(",");
                writer.write("{");
                for (int i = 1; i <= colCount; i++) {
                    if (i > 1) writer.write(",");
                    writer.write("\"" + meta.getColumnName(i) + "\":");
                    String val = rs.getString(i);
                    writer.write(val == null ? "null" : "\"" + val.replace("\"", "\\\"") + "\"");
                }
                writer.write("}");
                first = false;
            }
            writer.write("]}");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private String buildQuery(String reportType, String startDate, String endDate,
                              String sortCol, String tenantId) {
        // tenantId comes from authenticated session attribute, considered trusted
        // sortCol is validated to be [a-zA-Z_]+ above
        String table = "rpt_" + reportType; // reportType is whitelisted
        return String.format(
            "SELECT * FROM %s WHERE tenant_id = '%s' AND created_at BETWEEN '%s' AND '%s' ORDER BY %s",
            table, tenantId, startDate, endDate, sortCol
        );
    }
}
